// Unit A: Requires linking adjustments (relocation)

extern unsigned long shared_base_addr;
extern void log_message(const char* msg);

// Data Relocation (e.g., R_X86_64_GLOB_DAT)
// 'base' is initialized here, but the value (address)
// of shared_base_addr is not known until linking.
unsigned long* base = &shared_base_addr;

void initialize_system() {
    *base = 0xFF0000;
}

// Code Relocation (e.g., R_X86_64_PC32)
// The CALL instruction's target address must be patched.
void send_status() {
    log_message("System Active");
}
